// Oto — bridge between the browser UI and the main process.
const { contextBridge, ipcRenderer } = require('electron');

const CHANNELS = new Set([
  'cmd', 'tab:open', 'search', 'blocked', 'download', 'download-tab', 'perm:ask', 'perm:cancel', 'screen:pick', 'screen:cancel', 'danger', 'window-fullscreen', 'overlay-sampled',
  'win-state', 'page-mouse', 'ext:create-tab', 'ext:select-tab', 'ext:remove-tab', 'ext:changed', 'ext:refused', 'glance', 'update', 'ctx:show', 'ctrl-hold', 'quick:open', 'account:status', 'drm:ready', 'save-failed', 'data-damaged',
]);

contextBridge.exposeInMainWorld('oto', {
  info: () => ipcRenderer.invoke('app:info'),
  changelog: () => ipcRenderer.invoke('app:changelog'),
  versions: () => ipcRenderer.invoke('app:versions'),
  loadState: () => ipcRenderer.invoke('state:load'),
  saveState: (s) => ipcRenderer.send('state:save', s),
  saveStateSync: (s) => ipcRenderer.sendSync('state:save-sync', s),
  setOverlay: (color, symbol, height) => ipcRenderer.send('win:overlay', { color, symbol, height }),
  captureStrip: (height) => ipcRenderer.invoke('win:capture-strip', height),
  pauseKeys: (on) => ipcRenderer.send('keys:pause', on),
  relaunch: () => ipcRenderer.send('app:relaunch'),
  metrics: () => ipcRenderer.invoke('perf:metrics'),
  freezeTab: (wcId, frozen) => ipcRenderer.invoke('tab:freeze', wcId, frozen),
  setTheme: (t) => ipcRenderer.send('theme:set', t),
  copy: (text) => ipcRenderer.send('clipboard:write', text),
  copyImage: (dataUrl) => ipcRenderer.send('clipboard:image', dataUrl),
  suggest: (engine, q) => ipcRenderer.invoke('suggest', engine, q),
  setBlocking: (on) => ipcRenderer.invoke('blocker:set', on),
  shield: {
    state: (url) => ipcRenderer.invoke('shield:state', url),
    site: (url, allow) => ipcRenderer.invoke('shield:site', url, allow),
    filters: (text) => ipcRenderer.invoke('shield:filters', text),
    pick: (url, sel) => ipcRenderer.invoke('shield:pick', url, sel),
    annoy: (on) => ipcRenderer.invoke('shield:annoy', on),
    level: (lvl) => ipcRenderer.invoke('shield:level', lvl),
    feature: (name, value) => ipcRenderer.invoke('shield:feature', name, value),
    update: () => ipcRenderer.invoke('shield:update'),
    stats: () => ipcRenderer.invoke('shield:stats'),
    fp: (on) => ipcRenderer.invoke('shield:fp', on),
    danger: (on) => ipcRenderer.invoke('shield:danger', on),
    dangerAllow: (host) => ipcRenderer.invoke('shield:dangerAllow', host),
    dangerUpdate: () => ipcRenderer.invoke('shield:dangerUpdate'),
    statsReset: () => ipcRenderer.invoke('shield:statsReset'),
  },
  replyPermission: (id, allow) => ipcRenderer.send('perm:reply', id, allow),
  showInFolder: (p) => ipcRenderer.send('shell:show', p),
  dlAction: (id, act) => ipcRenderer.send('dl:action', id, act),
  dlOpen: (p) => ipcRenderer.invoke('dl:open', p),
  dlExists: (paths) => ipcRenderer.invoke('dl:exists', paths),
  clearData: () => ipcRenderer.invoke('data:clear'),
  syncSettings: (p) => ipcRenderer.send('settings:sync', p),
  listPermissions: () => ipcRenderer.invoke('perm:list'),
  resetPermission: (key) => ipcRenderer.invoke('perm:reset', key),
  setPermission: (key, val) => ipcRenderer.invoke('perm:set', key, val),
  replyScreen: (id, sourceId, audio) => ipcRenderer.send('screen:reply', id, sourceId || null, !!audio),
  pwArm: (wcId, opts) => ipcRenderer.invoke('pw:arm', wcId, opts),
  pwFillInto: (wcId, id) => ipcRenderer.invoke('pw:fillInto', wcId, id),
  clearSite: (origin) => ipcRenderer.invoke('site:clear', origin),
  ctxDo: (act, arg) => ipcRenderer.send('ctx:do', act, arg),
  appMode: () => ipcRenderer.invoke('app:mode'),
  openAvocado: () => ipcRenderer.send('avocado:open'),
  qrSvg: (text) => ipcRenderer.invoke('qr:svg', text),
  phoneModel: () => ipcRenderer.invoke('phone:model'),
  phonePickModel: () => ipcRenderer.invoke('phone:pickModel'),
  phoneClearModel: () => ipcRenderer.invoke('phone:clearModel'),
  shotFull: (wcId) => ipcRenderer.invoke('shot:full', wcId),
  shotSave: (dataUrl) => ipcRenderer.invoke('shot:save', dataUrl),
  shotShow: (f) => ipcRenderer.send('shot:show', f),
  shotOpen: (f) => ipcRenderer.send('shot:open', f),
  openApp: (url) => ipcRenderer.send('app:open', url),
  installApp: (url, title, icon) => ipcRenderer.invoke('app:install', url, title, icon),
  backupSave: (state, pass) => ipcRenderer.invoke('backup:save', state, pass),
  backupUnlock: (pass) => ipcRenderer.invoke('backup:unlock', pass),
  backupOpen: () => ipcRenderer.invoke('backup:open'),
  backupRestore: (pass) => ipcRenderer.invoke('backup:restore', pass),
  setAppIcon: (dataUrl) => ipcRenderer.send('app:icon', dataUrl),
  makeDefaultBrowser: () => ipcRenderer.invoke('app:default-browser'),
  // window buttons
  winMin: () => ipcRenderer.send('win:min'),
  winMax: () => ipcRenderer.send('win:max'),
  winClose: () => ipcRenderer.send('win:close'),
  cursor: () => ipcRenderer.invoke('win:cursor'),
  diagInfo: () => ipcRenderer.invoke('diag:info'),
  saveReport: (text) => ipcRenderer.invoke('diag:save', text),
  updateStatus: () => ipcRenderer.invoke('update:status'),
  updateCheck: () => ipcRenderer.invoke('update:check'),
  updateInstall: () => ipcRenderer.send('update:install'),
  ownerUnlock: (key) => ipcRenderer.invoke('owner:unlock', key),
  ownerLock: () => ipcRenderer.invoke('owner:lock'),
  ownerStatus: () => ipcRenderer.invoke('owner:status'),
  ownerProof: (msg) => ipcRenderer.invoke('owner:proof', msg),
  // extensions
  extTabReady: (id, wcId) => ipcRenderer.send('ext:tab-ready', id, wcId),
  extActive: (wcId) => ipcRenderer.send('ext:active', wcId),
  extList: () => ipcRenderer.invoke('ext:list'),
  extInstallFile: () => ipcRenderer.invoke('ext:install-file'),
  extLoadFolder: () => ipcRenderer.invoke('ext:load-folder'),
  extRemove: (id) => ipcRenderer.invoke('ext:remove', id),
  // passwords (the UI never gets passwords in bulk — only one, when you pick it)
  pwStatus: () => ipcRenderer.invoke('pw:status'),
  pwList: () => ipcRenderer.invoke('pw:list'),
  pwForOrigin: (url) => ipcRenderer.invoke('pw:forOrigin', url),
  pwCheck: (url, u, p) => ipcRenderer.invoke('pw:check', url, u, p),
  pwSave: (url, u, p) => ipcRenderer.invoke('pw:save', url, u, p),
  drmStatus: () => ipcRenderer.invoke('drm:status'),
  drmInstall: () => ipcRenderer.invoke('drm:install'),
  pwGet: (id, purpose) => ipcRenderer.invoke('pw:get', id, purpose),
  account: {
    status: () => ipcRenderer.invoke('account:status'),
    signup: (e, p) => ipcRenderer.invoke('account:signup', e, p),
    signin: (e, p) => ipcRenderer.invoke('account:signin', e, p),
    signout: () => ipcRenderer.invoke('account:signout'),
    forgot: (e) => ipcRenderer.invoke('account:forgot', e),
    resetWithCode: (e, c, p) => ipcRenderer.invoke('account:resetWithCode', e, c, p),
    confirmWithCode: (e, c, p) => ipcRenderer.invoke('account:confirmWithCode', e, c, p),
    resendConfirm: (e) => ipcRenderer.invoke('account:resendConfirm', e),
    oldPassword: (p) => ipcRenderer.invoke('account:oldPassword', p),
    startFresh: () => ipcRenderer.invoke('account:startFresh'),
    changePassword: (a, b) => ipcRenderer.invoke('account:changePassword', a, b),
    deleteCloud: () => ipcRenderer.invoke('account:deleteCloud'),
    push: (sections, summary) => ipcRenderer.invoke('account:push', sections, summary),
    pull: (o) => ipcRenderer.invoke('account:pull', o),
    peek: () => ipcRenderer.invoke('account:peek'),
    devicesBeat: (info) => ipcRenderer.invoke('devices:beat', info),
    devicesSend: (id, url, title) => ipcRenderer.invoke('devices:send', id, url, title),
    devicesForget: (id) => ipcRenderer.invoke('devices:forget', id),
  },
  pwUpdate: (id, patch) => ipcRenderer.invoke('pw:update', id, patch),
  pwDelete: (id) => ipcRenderer.invoke('pw:delete', id),
  pwImport: () => ipcRenderer.invoke('pw:import'),
  pwExport: () => ipcRenderer.invoke('pw:export'),
  // bookmarks import
  bookmarkSources: () => ipcRenderer.invoke('bm:sources'),
  importBookmarks: (id) => ipcRenderer.invoke('bm:import', id),
  on: (channel, fn) => {
    if (CHANNELS.has(channel)) ipcRenderer.on(channel, (_e, ...args) => fn(...args));
  },
});

// The extension toolbar element (<browser-action-list>) used in Oto's top strip.
try {
  __otoBrowserAction.injectBrowserAction();
} catch (err) {
  console.warn('[oto] extension toolbar unavailable', err && err.message);
}
